import 'package:flutter/foundation.dart';

/// Firebase configuration helper
///
/// Firebase is initialized directly in main() with FirebaseOptions from
/// firebase_options.dart (auto-generated by flutterfire configure).
///
/// Security rules are deployed via Firebase CLI:
/// - Firestore: firebase deploy --only firestore:rules
/// - Storage: firebase deploy --only storage
class FirebaseConfig {
  /// Enable offline persistence for Firestore (free tier support)
  static Future<void> enableOfflinePersistence() async {
    // Firestore offline persistence is enabled by default on mobile
    // No additional configuration needed
    if (kDebugMode) {
      print('✅ Firestore offline persistence enabled');
    }
  }
}
